/* 索引：按 id 查、按文体查 */
(function () {
  window.ZHAOMING_ALL = window.POEMS_ZHAOMING;

  window.getZhaomingById = function (id) {
    return window.POEMS_ZHAOMING.filter(function (p) { return p.id === id; })[0] || null;
  };

  /** 按 gradeGroup（文体 / 文体·小类）聚合成组，组内保持原书次第 */
  window.getZhaomingGroups = function () {
    var groups = [];
    window.POEMS_ZHAOMING.forEach(function (p) {
      var g = p.gradeGroup || "其他";
      var hit = groups.filter(function (it) { return it.name === g; })[0];
      if (!hit) { hit = { name: g, items: [] }; groups.push(hit); }
      hit.items.push(p);
    });
    return groups;
  };

  /** 已收录译文（原文与译文齐备）的篇数。
      正文收归主表后，条目只存归属、正文在 data/text-master.js——
      数之前先按 textRef 取回，否则会把已译的算成「待译」。 */
  window.zhaomingDoneCount = function () {
    return window.POEMS_ZHAOMING.filter(function (raw) {
      var p = (typeof window.masterTextOf === "function")
        ? window.masterTextOf(raw, "zhaoming") : raw;
      return p.text && p.translation;
    }).length;
  };

  /** 已收录原文的篇数（本集原文全收，等于总篇数） */
  window.zhaomingTextCount = function () {
    return window.POEMS_ZHAOMING.filter(function (p) { return !!p.text; }).length;
  };
})();

